     1	// Event Service - Unified interface for fetching events from multiple sources
     2	// This architecture allows easy addition of new event sources in the future
     3	
     4	import { fetchTicketmasterEvents } from './sources/ticketmaster.js';
     5	import { fetchKulturhusetEvents } from './sources/kulturhuset.js';
     6	import { fetchKulturhusetBarnUngEvents } from './sources/kulturhusetBarnUng.js';
     7	import { fetchDebaserEvents } from './sources/debaser.js';
     8	import { fetchStockholmLiveEvents } from './sources/stockholmlive.js';
     9	import { fetchFryshusetEvents } from './sources/fryshuset.js';
    10	import { fetchSlakthusetEvents } from './sources/slakthuset.js';
    11	import { fetchMalmöLiveEvents } from './sources/malmolive.js';
    12	import { fetchTele2ArenaEvents } from './sources/tele2arena.js';
    13	import { fetchFriendsArenaEvents } from './sources/friendsarena.js';
    14	import { fetchFotografiskaEvents } from './sources/fotografiska.js';
    15	import { fetchBerwaldhallenEvents } from './sources/berwaldhallen.js';
    16	import { fetchMalmöOperaEvents } from './sources/malmoopera.js';
    17	import { fetchSödraTeaternEvents } from './sources/sodrateatern.js';
    18	import { fetchAviciiArenaEvents } from './sources/aviciiarena.js';
    19	import { fetchAnnexetEvents } from './sources/annexet.js';
    20	import { fetchEventPulseEvents } from './sources/eventpulse.js';
    21	
    22	// Available event sources
    23	export const EVENT_SOURCES = {
    24	  EVENTPULSE: 'eventpulse',
    25	  TICKETMASTER: 'ticketmaster',
    26	  KULTURHUSET: 'kulturhuset',
    27	  KULTURHUSET_BARN_UNG: 'kulturhuset-barn-ung',
    28	  DEBASER: 'debaser',
    29	  STOCKHOLM_LIVE: 'stockholmlive',
    30	  FRYSHUSET: 'fryshuset',
    31	  SLAKTHUSET: 'slakthuset',
    32	  MALMO_LIVE: 'malmo-live',
    33	  MALMO_OPERA: 'malmo-opera',
    34	  SODRA_TEATERN: 'sodra-teatern',
    35	  AVICII_ARENA: 'avicii-arena',
    36	  ANNEXET: 'annexet',
    37	  TELE2_ARENA: 'tele2-arena',
    38	  FRIENDS_ARENA: 'friends-arena',
    39	  FOTOGRAFISKA: 'fotografiska',
    40	  BERWALDHALLEN: 'berwaldhallen',
    41	};
    42	
    43	// API keys (loaded from environment)
    44	// Uses fixed .env path: /Users/claudgashi/clawdbot/Workspace/EventPulse/project/EventPulse/project/tools/tomorPulseForge/.env
    45	const TICKETMASTER_API_KEY = process.env.TICKETMASTER_API_KEY || null;
    46	
    47	/**
    48	 * Fetch events from a specific source
    49	 * @param {string} source - Source identifier from EVENT_SOURCES
    50	 * @param {Object} options - Fetch options (source-specific)
    51	 * @returns {Promise<Event[]>} - Array of events in internal format
    52	 */
    53	async function fetchFromSource(source, options = {}) {
    54	  switch (source) {
    55	    case EVENT_SOURCES.EVENTPULSE:
    56	      return await fetchEventPulseEvents(options);
    57	    case EVENT_SOURCES.TICKETMASTER:
    58	      return await fetchTicketmasterEvents(TICKETMASTER_API_KEY, options);
    59	    case EVENT_SOURCES.KULTURHUSET:
    60	      return await fetchKulturhusetEvents(options);
    61	    case EVENT_SOURCES.KULTURHUSET_BARN_UNG:
    62	      return await fetchKulturhusetBarnUngEvents(options);
    63	    case EVENT_SOURCES.DEBASER:
    64	      return await fetchDebaserEvents(options);
    65	    case EVENT_SOURCES.STOCKHOLM_LIVE:
    66	      return await fetchStockholmLiveEvents(options);
    67	    case EVENT_SOURCES.FRYSHUSET:
    68	      return await fetchFryshusetEvents(options);
    69	    case EVENT_SOURCES.SLAKTHUSET:
    70	      return await fetchSlakthusetEvents(options);
    71	    case EVENT_SOURCES.MALMO_LIVE:
    72	      return await fetchMalmöLiveEvents(options);
    73	    case EVENT_SOURCES.TELE2_ARENA:
    74	      return await fetchTele2ArenaEvents(options);
    75	    case EVENT_SOURCES.FRIENDS_ARENA:
    76	      return await fetchFriendsArenaEvents(options);
    77	    case EVENT_SOURCES.FOTOGRAFISKA:
    78	      return await fetchFotografiskaEvents(options);
    79	    case EVENT_SOURCES.BERWALDHALLEN:
    80	      return await fetchBerwaldhallenEvents(options);
    81	    case EVENT_SOURCES.MALMO_OPERA:
    82	      return await fetchMalmöOperaEvents(options);
    83	    case EVENT_SOURCES.SODRA_TEATERN:
    84	      return await fetchSödraTeaternEvents(options);
    85	    case EVENT_SOURCES.AVICII_ARENA:
    86	      return await fetchAviciiArenaEvents(options);
    87	    case EVENT_SOURCES.ANNEXET:
    88	      return await fetchAnnexetEvents(options);
    89	    default:
    90	      console.warn(`Unknown event source: ${source}`);
    91	      return [];
    92	  }
    93	}
    94	
    95	/**
    96	 * Fetch events from all enabled sources
    97	 * @param {Object} options - Common fetch options
    98	 * @param {string[]} [options.sources] - Array of source identifiers (default: all)
    99	 * @param {number} [options.limit] - Events per source
   100	 * @param {number} [options.page] - Page number
   101	 * @param {string} [options.endDate] - End date filter
   102	 * @returns {Promise<Event[]>} - Combined and deduplicated array of events
   103	 */
   104	export async function fetchEvents(options = {}) {
   105	  const {
   106	    sources = [
   107	      EVENT_SOURCES.KULTURHUSET,
   108	      EVENT_SOURCES.TICKETMASTER,
   109	      EVENT_SOURCES.DEBASER,
   110	      EVENT_SOURCES.MALMO_LIVE,
   111	      EVENT_SOURCES.STOCKHOLM_LIVE,
   112	      EVENT_SOURCES.TELE2_ARENA,
   113	      EVENT_SOURCES.FRIENDS_ARENA,
   114	      EVENT_SOURCES.AVICII_ARENA,
   115	      EVENT_SOURCES.ANNEXET,
   116	      EVENT_SOURCES.FOTOGRAFISKA,
   117	      EVENT_SOURCES.BERWALDHALLEN,
   118	      EVENT_SOURCES.SODRA_TEATERN,
   119	      // EVENT_SOURCES.EVENTPULSE, // Disabled - returns synthetic data only
   120	      // EVENT_SOURCES.MALMO_OPERA, // Returns 0 events
   121	    ],
   122	    limit = 20,
   123	    page = 0,
   124	    endDate = null,
   125	  } = options;
   126	
   127	  // Fetch from each source in parallel
   128	  const results = await Promise.all(
   129	    sources.map(source => 
   130	      fetchFromSource(source, { limit, page, endDate })
   131	        .catch(err => {
   132	          console.error(`Error fetching from ${source}:`, err);
   133	          return [];
   134	        })
   135	    )
   136	  );
   137	
   138	  // Combine and deduplicate events by ID
   139	  const allEvents = results.flat();
   140	  const uniqueEvents = [];
   141	  const seenIds = new Set();
   142	
   143	  for (const event of allEvents) {
   144	    if (!seenIds.has(event.id)) {
   145	      seenIds.add(event.id);
   146	      uniqueEvents.push(event);
   147	    }
   148	  }
   149	
   150	  // Sort by date and time
   151	  uniqueEvents.sort((a, b) => {
   152	    if (!a.date && !b.date) return 0;
   153	    if (!a.date) return 1;
   154	    if (!b.date) return -1;
   155	    const dateCompare = a.date.localeCompare(b.date);
   156	    if (dateCompare !== 0) return dateCompare;
   157	    if (!a.time && !b.time) return 0;
   158	    if (!a.time) return 1;
   159	    if (!b.time) return -1;
   160	    return a.time.localeCompare(b.time);
   161	  });
   162	
   163	  return uniqueEvents;
   164	}
   165	
   166	/**
   167	 * Fetch events from a single source (convenience function)
   168	 * @param {string} source - Source identifier
   169	 * @param {Object} options - Fetch options
   170	 * @returns {Promise<Event[]>} - Array of events
   171	 */
   172	export async function fetchEventsFromSource(source, options = {}) {
   173	  return await fetchFromSource(source, options);
   174	}
